  state.scoreChoices=refs;const chooser=$('#overlapChoices');chooser.replaceChildren();
  refs.forEach((r,i)=>{const t=projectNow().tracks.find(t=>t.id===r.track);chooser.append(new Option(t.name+' · '+pName(r.p),String(i)));});
  chooser.hidden=refs.length<2;chooser.value=String(refs.indexOf(preferred));
