   Object.defineProperty(MP,'wake',{configurable:true,enumerable:true,get:()=>awakeLegacy,set(s){
    const old=awakeLegacy;awakeLegacy=s;
    if(old&&old!==s&&!old.released){try{Promise.resolve(old.release()).catch(()=>{});}catch(_){}}
    if(s){awake?.adopt(s,!!MP.running);if(s.released)awakeLegacy=null;}
   }});
