async function gsRead(files){if(!files?.length)return;const token=++gs.token;gs.task=true;gsStop();gsControls();gsMessage('게임 악기 구조와 반복 구간을 읽습니다…');try{if(files.length>2)throw Error('SPC/VAB 하나 또는 VH+VB 두 개를 선택하세요.');if(files.some(f=>f.size>PianoGameSoundCore.MAX.input))throw Error('입력은 파일당 32MiB 이하입니다.');const f=files.find(f=>!f.name.toLowerCase().endsWith('.vb'))||files[0],b=new Uint8Array(await f.arrayBuffer());if(token!==gs.token)return;let bank;if(f.name.toLowerCase().endsWith('.json')){if(f.size>PianoGameSoundCore.MAX.bank)throw Error('악기 묶음은 12MiB 이하입니다.');const raw=JSON.parse(new TextDecoder().decode(b));if(raw.format==='piano-game-instrument')bank={name:raw.name,items:[PianoGameSoundCore.validate(raw)]};else if(raw.format==='piano-game-bank'&&raw.version===1&&Array.isArray(raw.items)&&raw.items.length<=256)bank={name:PianoGameSoundCore.safeName(raw.name),items:raw.items.map(PianoGameSoundCore.validate)};else throw Error('게임 악기 묶음 JSON이 아닙니다.');}
 else if(new TextDecoder().decode(b.subarray(0,4))==='pBAV'){const body=files.find(x=>/\.vb$/i.test(x.name));bank=PianoGameSoundCore.vab(b,body?new Uint8Array(await body.arrayBuffer()):null,f.name);}else bank=PianoGameSoundCore.spc(b,f.name);if(token!==gs.token)return;gsSetBank(bank);gs.last={type:bank.sourceType||'instrument-bank',count:bank.items.length,observed:bank.items.filter(a=>a.source.observed).length,aiCalls:0,gameSpecificDriver:false};gsMessage(bank.items.filter(a=>a.source.candidateQuality!=='low-confidence').length+'개 악기/주요 후보를 읽었습니다. 들어보고 등록하세요. 아직 곡의 음표는 바꾸지 않았습니다.');}catch(e){if(token===gs.token)gsMessage('읽기 실패: '+e.message+' 기존 곡은 그대로입니다.',true);}finally{if(token===gs.token){gs.task=false;gsControls();}}}
async function gsPlay(pitch){if(gs.task)return;gsStop();gsDropTransient();const token=++gs.playToken,a=gsDraft(),id=SoundBank.registerLocal(a);gs.transient.add(id);ensureCtx();await ctx.resume();if(token!==gs.playToken)return;let lease;try{lease=await SoundBank.prepare([{id,notes:[{p:pitch}]}],{owner:'game-audition',isCurrent:()=>gs.open&&token===gs.playToken});if(token!==gs.playToken){lease.release();return;}gs.lease=lease;gs.voices.push(makeVoice(INST[id],pitch,.65,ctx.currentTime+.02,.65,master,null));gsMessage('미리 듣기: '+a.name+' · '+pName(pitch)+' · '+(a.source.builtin?'칩 파형 재현':'가져온 파일의 소리'));setTimeout(()=>{if(token===gs.playToken){gs.lease?.release();gs.lease=null;SoundBank.cleanUnused({why:'game-audition-finished'});}},Math.ceil((.75+a.envelope.release)*1000));}catch(e){lease?.release();gsMessage(e.message,true);}}
function gsDbWrite(items,remove=false){return new Promise((resolve,reject)=>{if(!gs.db)return reject(Error('악기 보관함 저장 불가'));let done=false,tx;const timer=setTimeout(()=>{try{tx?.abort();}catch(_){}finish(Error('악기 보관함 저장 시간 초과'));},6000),finish=e=>{if(done)return;done=true;clearTimeout(timer);e?reject(e):resolve();};try{tx=gs.db.transaction('assets','readwrite');tx.oncomplete=()=>finish();tx.onerror=tx.onabort=()=>finish(tx.error||Error('악기 보관함 저장 실패'));const store=tx.objectStore('assets');for(const a of items)remove?store.delete(a.id):store.put(a);}catch(e){finish(e);}});}
async function gsRemember(items){items=items.map(PianoGameSoundCore.validate);const combined=new Map(gs.library);for(const a of items)combined.set(a.id,a);if(combined.size>256||JSON.stringify([...combined.values()]).length>16*1024*1024)throw Error('악기 보관함 256개/16MiB 한도입니다. 사용하지 않는 보관함 항목을 파일로 백업하고 제거하세요. 곡에 사용 중인 악기는 곡 안에도 남습니다.');let saved=true;try{await gsDbWrite(items);}catch(e){saved=false;gs.dbStatus=e.name==='QuotaExceededError'?'악기 보관함 공간 부족 · 이번 세션에서 사용 중':'영구 보관 불가 · 이번 세션에서 사용 중';}for(const a of items){SoundBank.registerLocal(a);gs.library.set(a.id,a);gs.transient.delete(a.id);}if(saved)gs.dbStatus='이 브라우저에 보관됨';gsControls();return saved;}
async function gsRegister(){if(gs.task||!gs.bank)return;const items=gs.bank.items.filter((_,i)=>!gs.excluded.has(i)).map(a=>a.id===gs.bank.items[gs.current].id?gsDraft():a);if(!items.length)return gsMessage('등록할 악기를 체크하세요.',true);gs.task=true;gsControls();try{const saved=await gsRemember(items);if(!gs.excluded.has(gs.current))gs.bank.items[gs.current]=items.find(a=>a.id===gsDraft().id)||gs.bank.items[gs.current];gsRenderList();gsMessage(items.length+'개를 재생 악기 목록에 등록했습니다. '+(saved?'다른 곡에서도 보관함에서 고를 수 있습니다.':'영구 저장은 실패했습니다. 선택 악기 파일 저장으로 백업하세요.'));audioInstrumentRefresh();}catch(e){gsMessage(e.message,true);}finally{gs.task=false;gsControls();}}
