function cwAtomic(writes,deletes,expected,lastId,undo){return new Promise((resolve,reject)=>{if(!DB.db)return reject(Error('곡 저장소를 사용할 수 없습니다. «선택 채널만 곡 파일로 저장»을 사용하세요. 원곡은 변경하지 않았습니다.'));let tx,done=false,issue=null;const finish=e=>{if(done)return;done=true;clearTimeout(timer);audioStorageResult(e);e?reject(e):resolve();};const timer=setTimeout(()=>{issue=Error('저장 확인 시간 초과 · 원곡은 변경하지 않았습니다.');try{tx?.abort();}catch(_){}finish(issue);},12000);try{tx=DB.db.transaction(['projects','meta'],'readwrite');tx.oncomplete=()=>finish();tx.onerror=tx.onabort=()=>finish(issue||tx.error||Error('저장 취소 · 원곡은 변경하지 않았습니다.'));const store=tx.objectStore('projects');let left=expected.size;const apply=()=>{if(issue)return;for(const p of writes)store.put(p);for(const id of deletes)store.delete(id);if(lastId)tx.objectStore('meta').put(lastId,'last');tx.objectStore('meta').put(undo,'psn-channel-composer-undo-v1');};if(!left)apply();for(const [id,sig]of expected){const r=store.get(id);r.onerror=()=>{issue=r.error;};r.onsuccess=()=>{if(ChannelComposer.stamp(r.result)!==sig){issue=Error('다른 화면에서 원곡/대상 곡이 변경되었습니다. 목록을 새로 읽고 다시 선택하세요. 아무 채널도 옮기거나 삭제하지 않았습니다.');tx.abort();return;}if(--left===0)apply();};}}catch(e){issue=e;try{tx?.abort();}catch(_){}finish(e);}});}
