 for(const [id,fn]of [['cwOpenMain',cwOpen],['cwClose',cwClose],['cwRefresh',cwRefresh],['cwSave',cwSave],['cwExport',cwExport],['cwUndo',cwUndo],['cwClear',()=>{cw.basket.clear();cwRender();}],['cwFilesButton',()=>$('#cwFiles').click()],['cwTrackCopy',b=>cwOpen(b,true)],['cwTrackExport',async b=>{if(await cwOpen(b,true))await cwExport();}],['cwTrackDelete',cwDeleteTrack],['cwLocalMain',()=>lsOpen()]])listen($('#'+id),'click',guarded(fn));listen($('#cwFiles'),'change',guarded(e=>{const fs=[...e.target.files];e.target.value='';return cwReadFiles(fs);}));for(const id of ['cwSourceSong','cwDestination','cwTiming','cwAudible'])listen($('#'+id),'change',cwRender);for(const id of ['cwNewName','cwBpm'])listen($('#'+id),'input',()=>{cwRender();});listen($('#songWorkspace'),'click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.cwPick)cwPick($('#cwSourceSong').value,b.dataset.cwPick);if(b.dataset.cwRemove){cw.basket.delete(b.dataset.cwRemove);cwRender();}});listen($('#songWorkspace'),'change',e=>{if(e.target.dataset.cwCheck){const tid=e.target.dataset.cwCheck,sid=$('#cwSourceSong').value;e.target.checked?cwPick(sid,tid):cw.basket.delete(cwKey(sid,tid));cwRender();return;}const key=e.target.dataset.cwSourceAction;if(key&&cw.basket.has(key)){cw.basket.get(key).action=e.target.value;cwRender();}});listen($('#songWorkspace'),'keydown',e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();cwClose();}if(e.key==='Tab'){const f=focusables($('#songWorkspace')),at=f.indexOf(root.activeElement);if(e.shiftKey&&at<=0){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&at===f.length-1){e.preventDefault();f[0]?.focus();}}});
 listen($('#cwInspectorToggle'),'click',()=>{const open=cw.inspector.classList.toggle('cw-expanded');$('#cwInspectorToggle').setAttribute('aria-expanded',String(open));text('#cwInspectorToggle',open?'설정 접기':'채널 설정');});listen($('#cwTrackSearch'),'input',()=>{cw.inspectorSig='';cwInspectorSync();});listen($('#cwTrackInstrument'),'change',guarded(async e=>{const t=trackNow(),id=e.target.value;if(t)await audioApplyInstrument(t,id);cw.inspectorSig='';cwInspectorSync();}));listen($('#cwTrackName'),'change',()=>{const t=trackNow();if(!t||cwBlocked())return;t.name=$('#cwTrackName').value.trim()||t.name;renderTracks();scheduleSave();cw.inspectorSig='';sync();});listen($('#cwTrackVolume'),'input',()=>{const t=trackNow();if(!t||cwBlocked())return;t.volume=Number($('#cwTrackVolume').value);applyTrackGains();scheduleSave();});for(const [id,field]of [['cwTrackMute','muted'],['cwTrackSolo','solo']])listen($('#'+id),'click',()=>{const t=trackNow();if(!t||cwBlocked())return;t[field]=!t[field];if(field==='muted'&&t.muted)t.solo=false;applyTrackGains();renderTracks();scheduleSave();cw.inspectorSig='';sync();});const originalSync=uiSync;uiSync=function(){originalSync();cwInspectorSync();text('#cwCurrentBanner','작업 중인 곡: «'+(projectNow()?.name||'새 곡')+'» · '+(projectNow()?.tracks.length||0)+'개 채널');};
