async function cwImportDestination(mode,name){
 if(mode==='append')return projectNow();if(ui.task||cw.task||lc.pending)throw Error('다른 파일 작업이 진행 중입니다.');
 const next=newProject(String(name||'').trim().slice(0,120));
 const result=await lcTransition(next,{keep:ri.open?'retro':gs.open?'gameSound':null});
 if(!result){const e=Error('사용자가 곡 전환을 취소했습니다.');e.name='AbortError';throw e;}return result;
}

function cwAskAudioDestination(filename){return new Promise(resolve=>{showOverlay('녹음 파일을 어느 곡에 넣을까요?',null);const box=by('ovBtns');box.style.flexWrap='wrap';const label=document.createElement('label');label.style.cssText='display:grid;gap:8px;flex-basis:100%;text-align:left';label.textContent='저장 대상';const select=document.createElement('select');select.append(new Option('＋ 별도의 새 곡 · 기본','new'),new Option('현재 곡: '+projectNow().name+'에 채널 추가','append'));const input=document.createElement('input');input.value=filename.replace(/\.[^.]+$/,'').slice(0,120);input.maxLength=120;input.setAttribute('aria-label','새 곡 이름');label.append(select,input);const cancel=document.createElement('button'),ok=document.createElement('button');cancel.textContent='취소';ok.textContent='선택한 곡에 가져오기';cancel.onclick=()=>{hideOverlay();resolve(null);};select.onchange=()=>input.disabled=select.value!=='new';ok.onclick=()=>{const mode=select.value,name=input.value.trim();hideOverlay();resolve({mode,name});};box.append(label,cancel,ok);select.focus();});}
function cwImportWire(){const oldJson=importJson;importJson=cwOpenSongFile;listeners.push(()=>importJson=oldJson);const audio=by('fileAudio'),old=audio.onchange;audio.onchange=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;const target=await cwAskAudioDestination(f.name);if(!target)return;try{await cwImportDestination(target.mode,target.name);await old({target:{files:[f],value:''}});}catch(err){notify('가져오지 않았습니다: '+err.message);}};listeners.push(()=>audio.onchange=old);const b=makeEl('button','primary','이 악기로 별도의 새 곡');b.id='gsNewSong';$('#gsNew').before(b);$('#gsNew').textContent='현재 곡에 빈 채널 추가';listen(b,'click',guarded(async()=>{if(gs.task)return;const a=gsDraft();await cwImportDestination('new','');await gsUse(true);}));}

 /* Compressed-only cache management: uses the same pinned canonical URLs as
 * SoundBank.obtain, never decodes samples while downloading or restoring. */
const ls={open:false,task:false,controller:null,token:0,cached:0,bytes:0,last:'',opener:null};
function lsMessage(s,error=false){ls.last=String(s);text('#lsStatus',s);$('#lsStatus').dataset.error=String(error);}
function lsJobs(id,scope='all'){const b=SoundBank.banks.get(id);if(!b||b.local)return[];let keys=b.keys;if(scope==='song'){const pitches=(projectNow()?.tracks||[]).filter(t=>t.instrument===id).flatMap(t=>t.notes||[]);if(!pitches.length)pitches.push({p:60},{p:64},{p:67},{p:72});keys=[...new Map(pitches.flatMap(n=>SoundBank.keysFor(id,n.p+(INST[id]?.transpose||0))).map(k=>[k.file,k])).values()];}return keys.map(k=>({id,key:k.file,url:SoundBank.urls(b,k)[0],urls:SoundBank.urls(b,k)}));}
function lsControls(){for(const id of ['lsInstrument','lsScope','lsSearch','lsDownload','lsRefresh','lsExport','lsImportButton','lsPersistent','lsRemove'])$('#'+id).disabled=ls.task;$('#lsStop').disabled=!ls.task;$('#lsClose').disabled=false;}
function lsStop(){ls.token++;ls.controller?.abort();ls.controller=null;}
function lsClose(){lsStop();ls.open=false;state.localSamples=false;$('#localSamplesDialog').removeAttribute('open');syncInert();if(uiVisible(ls.opener))ls.opener.focus({preventScroll:true});}
function lsIsAudio(bytes){const b=new Uint8Array(bytes);return b.length>=4&&((b[0]===73&&b[1]===68&&b[2]===51)||(b[0]===255&&(b[1]&224)===224)||(b.length>=12&&b[0]===82&&b[1]===73&&b[2]===70&&b[3]===70&&b[8]===87&&b[9]===65&&b[10]===86&&b[11]===69)||(b[0]===79&&b[1]===103&&b[2]===103&&b[3]===83));}
function lsCatalog(){const e=$('#lsInstrument'),old=e.value||trackNow()?.instrument,q=$('#lsSearch').value.toLowerCase();SoundBank.fillOptions(e,INSTR.filter(i=>SoundBank.banks.has(i.id)&&!SoundBank.banks.get(i.id).local&&(!q||i.name.toLowerCase().includes(q))));if([...e.options].some(o=>o.value===old))e.value=old;}
async function lsOpen(opener){if(busy()||ui.task||cw.task)return notify('작업을 마친 뒤 음원 보관함을 여세요.');closeDialog('menu');if(cw.open)cwClose();if(au.open)audioClose();ls.opener=opener?.currentTarget||opener||root.activeElement;ls.open=true;state.localSamples=true;$('#localSamplesDialog').setAttribute('open','');syncInert();$('#lsSearch').value='';lsCatalog();if([...$('#lsInstrument').options].some(o=>o.value===trackNow()?.instrument))$('#lsInstrument').value=trackNow().instrument;lsControls();await lsRefresh();$('#lsInstrument').focus({preventScroll:true});}
async function lsStorage(){try{const e=await navigator.storage?.estimate?.(),p=await navigator.storage?.persisted?.();text('#lsStorage',`사이트 전체 저장 ${e?fmtBytes(e.usage||0)+' / '+fmtBytes(e.quota||0):'정보 제공 안 됨'} · 장기 보관 ${p?'허용됨':'미허용/확인 필요'}\n브라우저 데이터 삭제·비공개 모드 종료로 사라질 수 있으니 중요한 음원은 파일로 백업하세요.`);}catch(e){text('#lsStorage','브라우저 저장 상태를 확인하지 못했습니다.');}}
async function lsRefresh(){if(ls.task)return;const id=$('#lsInstrument').value,jobs=lsJobs(id,$('#lsScope').value),token=++ls.token;try{const cache=await caches.open(SoundBank.cacheName);let count=0,total=0;for(const j of jobs){const r=await cache.match(j.url);if(token!==ls.token)return;if(r){count++;total+=Number(r.headers.get('x-psn-bytes')||r.headers.get('content-length'))||(await r.blob()).size;}}ls.cached=count;ls.bytes=total;text('#lsCount',`${count} / ${jobs.length}개 음이 기기에 저장됨 · 압축 파일 ${fmtBytes(total)}\n${count===jobs.length&&jobs.length?'선택 범위는 오프라인 준비 완료':'받지 않은 음은 최초 사용 시 인터넷 필요'}`);lsMessage('저장 상태를 확인했습니다. 미리 받기는 재생 메모리를 사용하지 않습니다.');}catch(e){lsMessage('음원 보관함을 사용할 수 없습니다: '+e.message,true);}await lsStorage();}
async function lsGet(job,signal){let last;for(const url of job.urls){const c=new AbortController(),abort=()=>c.abort();signal.addEventListener('abort',abort,{once:true});const timer=setTimeout(abort,14000);try{if(signal.aborted)throw new DOMException('중지','AbortError');const r=await fetch(url,{signal:c.signal,credentials:'omit',mode:'cors'});if(!r.ok)throw Error('HTTP '+r.status);if(Number(r.headers.get('content-length'))>5*1024*1024)throw Error('음 하나의 파일은 5MiB 이하입니다.');const bytes=await r.arrayBuffer();if(!bytes.byteLength||bytes.byteLength>5*1024*1024)throw Error('음원 크기 오류');if(!lsIsAudio(bytes))throw Error('서버가 오디오가 아닌 파일을 반환했습니다.');return{bytes,type:r.headers.get('content-type')||'audio/mpeg'};}catch(e){if(signal.aborted)throw e;last=e;}finally{clearTimeout(timer);signal.removeEventListener('abort',abort);}}throw last||Error('다운로드 실패');}
async function lsDownload(){if(ls.task)return;const id=$('#lsInstrument').value,jobs=lsJobs(id,$('#lsScope').value);if(!jobs.length)return;ls.task=true;ls.controller=new AbortController();const token=++ls.token,signal=ls.controller.signal;lsControls();$('#lsProgress').value=0;let got=0,existing=0,errors=[],total=0;try{const cache=await caches.open(SoundBank.cacheName);for(let i=0;i<jobs.length;i++){if(signal.aborted||token!==ls.token)break;const j=jobs[i];lsMessage(`${INST[id].name}\n${i+1}/${jobs.length} · ${j.key} 저장 중…`);if(await cache.match(j.url))existing++;else{try{const r=await lsGet(j,signal);if(signal.aborted||token!==ls.token)break;if(total+r.bytes.byteLength>256*1024*1024)throw Error('이번 다운로드 256MiB 제한');await cache.put(j.url,new Response(r.bytes,{headers:{'content-type':r.type,'x-psn-bytes':r.bytes.byteLength}}));got++;total+=r.bytes.byteLength;}catch(e){if(signal.aborted)break;errors.push(j.key+': '+e.message);if(e.name==='QuotaExceededError')break;}}$('#lsProgress').value=(i+1)/jobs.length;}lsMessage(`${signal.aborted?'중지':'미리 받기 종료'} · 새로 저장 ${got}개 · 기존 보관 ${existing}개${errors.length?' · 실패 '+errors.length+'개\n'+errors.slice(0,3).join('\n'):''}\n저장에 성공한 음은 다음에 기기에서 불러옵니다.`,!!errors.length);}catch(e){lsMessage('미리 받기 실패: '+e.message,true);}finally{ls.task=false;ls.controller=null;lsControls();const message=ls.last;await lsRefresh();lsMessage(message,!!errors.length);}}
const lsDigest=async bytes=>{if(!crypto?.subtle)throw Error('음원 파일 검증에는 HTTPS 브라우저가 필요합니다.');return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),n=>n.toString(16).padStart(2,'0')).join('');};
async function lsPack(id){const jobs=lsJobs(id),cache=await caches.open(SoundBank.cacheName),entries=[],blobs=[];let total=0;for(const j of jobs){const r=await cache.match(j.url);if(!r)continue;const b=await r.blob();total+=b.size;if(total>256*1024*1024)throw Error('백업 파일 256MiB 제한');entries.push({id,key:j.key,size:b.size,type:b.type||'audio/mpeg',sha256:await lsDigest(await b.arrayBuffer())});blobs.push(b);}if(!entries.length)throw Error('기기에 저장된 음이 없습니다. 먼저 미리 받기를 사용하세요.');const meta=new TextEncoder().encode(JSON.stringify({format:'piano-local-sounds',version:1,revision:SoundBank.meta(id).revision,entries})),head=new Uint8Array(12);head.set(new TextEncoder().encode('PSNSND22'));new DataView(head.buffer).setUint32(8,meta.length,true);return new Blob([head,meta,...blobs],{type:'application/octet-stream'});}
async function lsRestore(file){if(file.size>257*1024*1024||file.size<12)throw Error('음원 파일 크기 오류');const head=new Uint8Array(await file.slice(0,12).arrayBuffer());if(new TextDecoder().decode(head.subarray(0,8))!=='PSNSND22')throw Error('우리집 연주실 음원 백업이 아닙니다.');const n=new DataView(head.buffer).getUint32(8,true);if(n>1048576||12+n>file.size)throw Error('잘못된 음원 목록 길이');const m=JSON.parse(await file.slice(12,12+n).text());if(m.format!=='piano-local-sounds'||m.version!==1||!Array.isArray(m.entries)||m.entries.length>256)throw Error('음원 목록 오류');let offset=12+n;const parts=[],seen=new Set();for(const e of m.entries){const j=lsJobs(e.id).find(j=>j.key===e.key);if(!j||m.revision!==SoundBank.meta(e.id).revision||!Number.isInteger(e.size)||e.size<1||e.size>5*1024*1024||offset+e.size>file.size||seen.has(j.url))throw Error('지원하지 않거나 손상된 음원 항목');seen.add(j.url);const part=file.slice(offset,offset+e.size);if(await lsDigest(await part.arrayBuffer())!==e.sha256)throw Error('음원 파일 검증 실패: '+e.key);parts.push({job:j,part,type:/^audio\/[a-z0-9.+-]+$/i.test(e.type)?e.type:'audio/mpeg'});offset+=e.size;}if(offset!==file.size)throw Error('음원 파일 뒤에 알 수 없는 데이터가 있습니다.');const cache=await caches.open(SoundBank.cacheName);let restored=0;for(const p of parts){await cache.put(p.job.url,new Response(p.part,{headers:{'content-type':p.type,'x-psn-bytes':p.part.size}}));restored++;}return restored;}
async function lsExport(){if(ls.task)return;ls.task=true;lsControls();try{const id=$('#lsInstrument').value,pack=await lsPack(id);await saveFile(safeName(INST[id].shortName||INST[id].name)+'.psnsounds',pack);lsMessage('기기에 보관한 음들을 파일로 저장했습니다. 원래 보관함은 유지합니다.');}catch(e){lsMessage(e.message,true);}finally{ls.task=false;lsControls();}}
async function lsImport(file){if(ls.task||!file)return;ls.task=true;lsControls();try{const n=await lsRestore(file);lsMessage(n+'개 음원을 기기 보관함에 복원했습니다. 인터넷 없이 필요한 음을 준비할 수 있습니다.');}catch(e){lsMessage('복원 실패: '+e.message+' 이미 보관 중인 다른 음원·곡은 삭제하지 않습니다.',true);}finally{ls.task=false;lsControls();await lsStorage();}}
async function lsRemove(){const id=$('#lsInstrument').value;if(ls.task||!await confirmBox('«'+INST[id].name+'»의 다운로드된 압축 음원만 삭제할까요? 곡과 녹음, 악기 설정은 남습니다.','다운로드 삭제'))return;const c=await caches.open(SoundBank.cacheName);for(const j of lsJobs(id))await c.delete(j.url);await lsRefresh();}
