 /* alpha.26: independent parts on one notation clock. No source notes are changed. */
const FullScoreCore=(()=>{
 const limit={parts:64,notes:30000,bars:1200},eps=1e-7;
 function build(tracks,options={},env={}){
  const empty=[],parts=[],selected=options.ids==null?null:new Set(options.ids.map(String));
  const eligible=(tracks||[]).filter(t=>!selected||selected.has(String(t.id)));
  let count=0;
  for(const [index,t] of (tracks||[]).entries()){
   if(!eligible.includes(t))continue;
   if(!t.notes?.length){empty.push({id:t.id,name:t.name||'이름 없는 채널',audio:!!t.audio,index:index+1});continue;}
   count+=t.notes.length;
   parts.push({id:t.id,name:t.name||'이름 없는 채널',index:index+1,instrument:t.instrument,muted:!!t.muted,solo:!!t.solo,notes:t.notes});
  }
  if(parts.length>limit.parts||count>limit.notes)throw Error('총보는 한 번에 64개 음표 채널·30,000음까지 표시합니다. 표시할 채널을 줄여 주세요. 원본은 변경하지 않았습니다.');
  const grand=options.layout==='grand',cfg={...(options.precision||{}),mode:options.precision?.mode==='legacy'?'precise':options.precision?.mode||'precise'};
  for(const part of parts){
   part.score=PrecisionCore.build([{id:part.id,notes:part.notes}],{split:grand?'hand':null,grid:options.grid||1,precision:cfg},env);
   const pitches=part.notes.map(n=>n.p).sort((a,b)=>a-b);
   part.clef=pitches[Math.floor(pitches.length/2)]<60?'bass':'treble';
   // Use the same subdivision across all parts, never a per-instrument time scale.
  }
  const globalGrid=parts.length?Math.min(...parts.map(p=>p.score.grid)):.25;
  if(cfg.mode==='precise')for(const part of parts)if(part.score.grid!==globalGrid){
   part.score=PrecisionCore.build([{id:part.id,notes:part.notes}],{split:grand?'hand':null,grid:options.grid||1,precision:{...cfg,division:Math.min(128,16/globalGrid),forcedGrid:globalGrid}},env);
  }
  const exemplar=parts[0]?.score,nBars=parts.length?Math.max(...parts.map(p=>p.score.nBars)):0;
  const rows=[];
  for(const part of parts){
   const score=part.score;
   while(score.measures.length<nBars){const i=score.measures.length,voices={treble:[],bass:[]};for(const st of ['treble','bass']){
     voices[st]=[PrecisionCore.splitDur(0,score.bar16,score.beat16).map(f=>({...f,start16:i*score.bar16+f.start16,rest:true,ps:[],refs:[],voice:0}))];
    }score.measures.push({treble:voices.treble.flat(),bass:voices.bass.flat(),voices});}
   score.nBars=nBars;
   const clefs=grand?['treble','bass']:[part.clef];
   for(const clef of clefs)rows.push({part,clef,sourceStaff:grand?clef:'treble',label:grand?(clef==='treble'?'오른손':'왼손'):'',first:clef===clefs[0]});
   delete part.notes;
  }
  return {kind:'full-score-v1',parts,rows,empty,nBars,count,grid:globalGrid,bar16:exemplar?.bar16||16,bpm:exemplar?.bpm||env.bpm||100,time:exemplar?.time||'4/4',key:exemplar?.key||env.key||'C',six:!!exemplar?.six,g16:exemplar?.g16||.15,grand,originalTimesUnchanged:true};
 }
 function paginate(model,available=900,bars=0){
  const plans=[];let next=[],width=0;
  for(let i=0;i<model.nBars;i++){
   const ticks=new Set();let maxChord=1;
   for(const row of model.rows)for(const v of row.part.score.measures[i].voices[row.sourceStaff])for(const f of v){ticks.add(f.start16);maxChord=Math.max(maxChord,f.ps.length);}
   const estimate=Math.max(185,70+ticks.size*30+Math.min(maxChord,5)*10);
   if(next.length&&((bars&&next.length>=bars)||(!bars&&width+estimate+100>available))){plans.push(next);next=[];width=0;}
   next.push({bar:i,estimate});width+=estimate;
  }
  if(next.length)plans.push(next);return plans;
 }
 const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 function musicXML(model,title=''){
  if(!model.parts.length)throw Error('음표가 있는 표시 채널을 선택하세요.');
  let xml='<?xml version="1.0" encoding="UTF-8"?>\n<score-partwise version="4.0"><work><work-title>'+escape(title)+'</work-title></work><part-list>';
  model.parts.forEach((p,i)=>xml+='<score-part id="P'+(i+1)+'"><part-name>'+escape(p.name)+'</part-name><part-abbreviation>CH '+p.index+'</part-abbreviation></score-part>');xml+='</part-list>';
  for(const [i,p]of model.parts.entries()){
   let inner=precisionMusicXML(p.score,title).split('<part id="P1">')[1].split('</part>')[0];
   if(!model.grand&&p.clef==='bass')inner=inner.replace('<sign>G</sign><line>2</line>','<sign>F</sign><line>4</line>');
   xml+='<part id="P'+(i+1)+'">'+inner+'</part>';
  }return xml+'</score-partwise>';
 }
 return Object.freeze({build,paginate,musicXML,limits:limit});
})();

