   ctx.setFont('Arial',10);ctx.fillText(fit(opt.instrumentName?.(p)||p.instrument||'','10px Arial'),20,y+54);
   ctx.fillText((p.muted?'음소거 · ':'')+(p.solo?'솔로 · ':'')+(model.grand?'양손 2단':'자동 음자리'),20,y+70);
   const r=document.createElementNS(NS,'rect');for(const [k,v]of Object.entries({x:12,y:y+14,width:gutter-25,height:model.grand?190:75,fill:'transparent',class:'fs-part-hit',tabindex:0,role:'button','aria-label':p.index+'번 '+p.name+' 채널 선택'}))r.setAttribute(k,v);r.dataset.fsPick=p.id;hits.push(r);
